716	                && GRADES.contains(k.substring(SettingRepository.TERMS_PREFIX.length())));
717	        boolean grace = k.startsWith(SettingRepository.GRACE_PREFIX)
718	                && GRADES.contains(k.substring(SettingRepository.GRACE_PREFIX.length()));
719	        boolean latePct = SettingRepository.LATE_PCT.equals(k);
720	        boolean policyDate = SettingRepository.POLICY_DATE.equals(k);
721	        boolean numberingFrom = SettingRepository.PERIOD_NUMBERING_FROM.equals(k);
722	        boolean graceDays = SettingRepository.GRACE_DAYS.equals(k);
723	        boolean entryDate = SettingRepository.ENTRY_DATE.equals(k);
724	        boolean pot = SettingRepository.POT.equals(k);
725	        boolean alertThreshold = SettingRepository.ALERT_THRESHOLD.equals(k);
726	        boolean fiscalStart = SettingRepository.FISCAL_START_MONTH.equals(k);
727	        boolean cap = SettingRepository.CAP.equals(k);
728	        boolean proofThreshold = SettingRepository.PROOF_THRESHOLD.equals(k);
729	        boolean gradeProofThreshold = k.startsWith(SettingRepository.PROOF_THRESHOLD_PREFIX)
730	                && GRADES.contains(k.substring(SettingRepository.PROOF_THRESHOLD_PREFIX.length()));
731	        proofThreshold = proofThreshold || gradeProofThreshold;
732	        boolean noteThreshold = SettingRepository.NOTE_THRESHOLD.equals(k);
733	        boolean parent = SettingRepository.PARENT.equals(k);
734	        boolean rounding = SettingRepository.ROUNDING.equals(k);
735	        boolean perm = k.startsWith(SettingRepository.PERM_PREFIX)
736	                && SettingRepository.PERMISSIONS.containsKey(k.substring(SettingRepository.PERM_PREFIX.length()));
737	        if (!parent && !rounding && !perm && !SettingRepository.CLERK_LIMIT.equals(k) && !cap && !proofThreshold && !noteThreshold && !floor && !terms && !grace && !latePct && !policyDate && !numberingFrom && !graceDays && !entryDate && !pot && !alertThreshold && !fiscalStart) {
738	            throw new InvalidSettingException("Unknown setting " + k);
739	        }
