741	        String by = request == null || request.by() == null ? "" : request.by().trim();
742	        String fromText = request == null || request.from() == null ? "" : request.from().trim();
743	        LocalDate from = null;
744	        if (!policyDate && !numberingFrom && !entryDate && !graceDays && !pot && !alertThreshold && !fiscalStart && !fromText.isEmpty()) {
745	            try {
746	                from = LocalDate.parse(fromText);
