756	            }
757	            if (value.equals(sheet)) {
758	                throw new InvalidSettingException("A sheet cannot be its own parent");
759	            }
760	            if (!sheets.exists(value)) {
761	                throw new InvalidSettingException("The parent must be a sheet that exists");
762	            }
763	            if (settings.hasAncestor(value, sheet)) {
764	                throw new InvalidSettingException("The parent cannot be a sheet that has this sheet as an ancestor");
765	            }
766	            values.set(new SettingValues(k, value, null, false, by));
767	            return;
768	        }
769	        if (perm) {
770	            if (value.isEmpty()) {
771	                values.set(new SettingValues(k, null, null, false, by));
772	                return;
773	            }
774	            List<String> roles = new ArrayList<>();
775	            for (String role : value.split(",", -1)) {
776	                String r = role.trim();
777	                if (!ROLES.contains(r)) {
778	                    throw new InvalidSettingException("A permission must be roles (clerk, steward) separated by commas, or blank");
779	                }
780	                if (!roles.contains(r)) {
781	                    roles.add(r);
782	                }
783	            }
