154	        number.set(new ClaimNumber(claim.number()));
155	        previous.set(new PreviousDue(claim.due(), claim.status()));
156	        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
157	                claim.note(), to, claim.number(), settledDue,
158	                change.action() == ClaimAction.OPEN ? change.by() : claim.openedBy(), claim.stated(), claim.statedDue(), claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(), claim.ref(), claim.tags()));
159	    }
160	
161	    /** Whether the claim cannot be opened for want of a note: its note is empty and its due is above the sheet's note
162	     *  threshold in force on its date (none: never; a due of n/a: never). */
163	    static boolean needsNote(Claim claim, PersonRepository people, RateRepository rates, SettingRepository settings,
164	            LateCharge late) {
165	        if (claim.note() != null && !claim.note().isBlank()) {
166	            return false;
167	        }
168	        BigDecimal threshold = settings.noteThreshold(claim.sheetId(), claim.date());
169	        if (threshold == null) {
170	            return false;
171	        }
172	        BigDecimal due = late.add(claim, due(claim, people, rates, late.rounding()),
173	                settings.floor(claim.sheetId(), claim.date()));
174	        return due != null && due.compareTo(threshold) > 0;
175	    }
176	
177	    private static BigDecimal due(Claim claim, PersonRepository people, RateRepository rates, Rounding rounding) {
178	        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
179	            return claim.statedDue();
180	        }
181	        Person person = people.find(claim.sheetId(), claim.personId());
182	        return person == null ? null : ClaimDue.live(claim, person.gradeOn(claim.date()), rates, rounding);
183	    }
184	}
