190	/** Reads the body: the action is open, settle, approve, reject (which needs a reason), void (with the void reason
191	 *  chosen, if any), resettle, delete or restore. */
192	public class ValidateClaimStatus {
193	    public void validate(@RequestBody ClaimStatusRequest request, Out<ClaimStatusChange> change)
194	            throws InvalidClaimStatusException {
195	        String action = request == null || request.action() == null ? "" : request.action().trim();
196	        ClaimAction taken = switch (action) {
197	            case "open" -> ClaimAction.OPEN;
198	            case "settle" -> ClaimAction.SETTLE;
199	            case "approve" -> ClaimAction.APPROVE;
200	            case "reject" -> ClaimAction.REJECT;
201	            case "void" -> ClaimAction.VOID;
202	            case "resettle" -> ClaimAction.RESETTLE;
203	            case "delete" -> ClaimAction.DELETE;
204	            case "restore" -> ClaimAction.RESTORE;
205	            default -> throw new InvalidClaimStatusException("The action must be open, settle, approve, reject, void, resettle, delete or restore");
206	        };
207	        ClaimStatus to = switch (taken) {
208	            case OPEN, REJECT -> ClaimStatus.OPEN;
209	            case SETTLE, APPROVE, RESETTLE -> ClaimStatus.SETTLED;
210	            case VOID -> ClaimStatus.VOID;
211	            case DELETE -> ClaimStatus.DELETED;
212	            case RESTORE -> ClaimStatus.DRAFT;
213	        };
214	        String reason = request.reason() == null ? "" : request.reason().trim();
215	        if (taken == ClaimAction.REJECT && reason.isEmpty()) {
216	            throw new InvalidClaimStatusException("A rejection needs a reason");
217	        }
218	        change.set(new ClaimStatusChange(taken, to, request.by() == null ? "" : request.by().trim(),
219	                taken == ClaimAction.REJECT || taken == ClaimAction.VOID ? reason : ""));
220	    }
221	}
