233	/** Writes CLAIM_OPENED, CLAIM_SETTLED, CLAIM_PENDING, CLAIM_APPROVED, CLAIM_REJECTED, CLAIM_VOIDED, CLAIM_RESETTLED, CLAIM_DELETED or CLAIM_RESTORED to the audit
234	 * file once the status is stored, ending with number=<number> when the claim has one; CLAIM_SETTLED and CLAIM_APPROVED
235	 * then end with the due they fixed (due=n/a when its grade had no rate), CLAIM_REJECTED with reason=<reason>, CLAIM_RESETTLED with old=<previous due> new=<new due>, and CLAIM_VOIDED of a SETTLED claim with reversed=<its frozen due>, and a CLAIM_VOIDED given a void reason with reason=<reason> last. Then writes the
236	 * figures the change moved (see Rollup). A settle, approve or re-settle that leaves the claim SETTLED first writes, after
237	 * its own line, one NOTIFY user=<watcher> person=<name> number=<number> per user watching the claim's person, in the
238	 * order they started watching. */
239	public class RecordClaimStatusChanged {
240	    public void record(@Val Claim claim, @Val ClaimStatusChange change, @Val ClaimNumber number, @Val PreviousDue previous,
241	            PersonRepository people, WatchRepository watches, @Val RollupBefore before, Rollup rollup, Audit audit) {
242	        String event = switch (change.action()) {
243	            case OPEN -> "CLAIM_OPENED";
244	            case SETTLE -> claim.status() == ClaimStatus.PENDING ? "CLAIM_PENDING" : "CLAIM_SETTLED";
245	            case APPROVE -> "CLAIM_APPROVED";
246	            case REJECT -> "CLAIM_REJECTED";
247	            case VOID -> "CLAIM_VOIDED";
248	            case RESETTLE -> "CLAIM_RESETTLED";
249	            case DELETE -> "CLAIM_DELETED";
250	            case RESTORE -> "CLAIM_RESTORED";
251	        };
252	        Person person = people.find(claim.sheetId(), claim.personId());
253	        audit.record(event + " sheet=" + claim.sheetId() + " by=" + change.by() + " person="
254	                + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
255	                + " date=" + claim.date() + (number.value() == null ? "" : " number=" + number.value())
256	                + (change.action() == ClaimAction.RESETTLE
257	                        ? " old=" + figure(previous.value()) + " new=" + figure(claim.due())
258	                        : claim.status() == ClaimStatus.SETTLED
259	                        ? " due=" + (claim.due() == null ? "n/a" : claim.due().toPlainString()) : "")
260	                + (change.action() == ClaimAction.REJECT ? " reason=" + change.reason() : "")
261	                + (change.action() == ClaimAction.VOID && previous.status() == ClaimStatus.SETTLED
262	                        ? " reversed=" + figure(previous.value()) : "")
263	                + (change.action() == ClaimAction.VOID && !change.reason().isEmpty() ? " reason=" + change.reason() : ""));
264	        if (person != null && claim.status() == ClaimStatus.SETTLED && (change.action() == ClaimAction.SETTLE
265	                || change.action() == ClaimAction.APPROVE || change.action() == ClaimAction.RESETTLE)) {
266	            for (String watcher : watches.watchers(claim.sheetId(), person.id())) {
267	                audit.record("NOTIFY sheet=" + claim.sheetId() + " by=" + change.by() + " user=" + watcher + " person="
268	                        + person.name() + " number=" + number.value());
269	            }
270	        }
271	        rollup.record(claim.sheetId(), change.by(), before);
272	    }
273	
274	    private static String figure(BigDecimal due) {
275	        return due == null ? "n/a" : due.toPlainString();
276	    }
277	}
