300	/**
301	 * Opens each selected claim that can be opened, in list order (people in list order, see PersonRepository#list; a person's
302	 * claims newest first): as the single open does, it must be a DRAFT whose due-by is not inside a closed period, nor one with an empty note whose due is above the note threshold
303	 * (see ApplyClaimStatus#needsNote), nor one that would take its person past its period's cap (see ClaimRules#overCap; those opened
304	 * before it in the same press count), takes its
305	 * number (see ClaimNumbering) and records who opened it, adds its OPEN line to its status log (see ClaimLog), then writes CLAIM_OPENED and the figures it moved (see Rollup).
306	 * A user whose role the sheet does not permit to open opens none. Each that cannot, or is not on the sheet, is left as it is and counted refused.
307	 */
308	public class OpenClaims {
309	    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenRequest request, ClaimRepository claims,
310	            PersonRepository people, RateRepository rates, PeriodRepository periods, SettingRepository settings, RoleRepository roles, SheetRepository sheets, Rollup rollup, Audit audit, ClaimLog log,
311	            Out<BulkOpenResult> result) {
312	        String sheet = sheetId.trim();
313	        Set<Long> selected = new HashSet<>(request.claimIds());
314	        List<Person> listed = people.list(sheet);
315	        Map<Long, Integer> personOrder = new HashMap<>();
316	        for (int i = 0; i < listed.size(); i++) {
317	            personOrder.put(listed.get(i).id(), i);
318	        }
319	        Map<Long, Person> byId = listed.stream().collect(Collectors.toMap(Person::id, (p) -> p));
320	        List<Claim> chosen = claims.list(sheet).stream().filter((c) -> selected.contains(c.id()))
321	                .sorted((a, b) -> Integer.compare(personOrder.getOrDefault(a.personId(), Integer.MAX_VALUE),
322	                        personOrder.getOrDefault(b.personId(), Integer.MAX_VALUE)))
323	                .toList();
324	        LateCharge late = LateCharge.of(sheet, sheets, settings, claims);
325	        int opened = 0;
326	        if (!settings.permits(sheet, "open", roles.roleOf(sheet, request.by()))) {
327	            chosen = List.of();
328	        }
329	        for (Claim claim : chosen) {
330	            if (claim.status() != ClaimStatus.DRAFT || periods.closedOn(sheet, claim.dueBy())
331	                    || ApplyClaimStatus.needsNote(claim, people, rates, settings, late)
332	                    || ClaimRules.overCap(claim, periods, claims)) {
333	                continue;
334	            }
335	            RollupBefore before = rollup.take(sheet);
336	            String number = ClaimNumbering.next(claim, claims, periods, settings, sheets);
337	            Claim toSave = new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
338	                    claim.note(), ClaimStatus.OPEN, number, claim.due(), request.by(), claim.stated(),
339	                    claim.statedDue(), claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(), claim.ref(), claim.tags());
340	            if (!claims.updateStatus(toSave, ClaimStatus.DRAFT)) {
341	                continue;
342	            }
343	            opened++;
344	            log.write(toSave, request.by());
345	            Person person = byId.get(claim.personId());
346	            audit.record("CLAIM_OPENED sheet=" + sheet + " by=" + request.by() + " person="
347	                    + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
348	                    + " date=" + claim.date() + " number=" + number);
349	            rollup.record(sheet, request.by(), before);
350	        }
351	        result.set(new BulkOpenResult(opened, selected.size() - opened));
352	    }
353	}
