363	/** The rules a claim must keep to be added to a person (see AddClaim), checked without writing anything. */
364	public final class ClaimRules {
365	
366	    private ClaimRules() {
367	    }
368	
369	    /** The claim's date (the sheet's entry date, else its today, when none was given) and the due-by it would be fixed with (see dueBy);
370	     *  a due-by inside a closed period or a date after the person's retirement date is refused, as is a negative amount that does not
371	     *  correct a SETTLED claim (see Corrections), or a reference already used on the sheet (see checkRef). */
372	    public static Checked check(Person person, ClaimValues values, SettingRepository settings, PeriodRepository periods,
373	            ClaimRepository claims, HolidayRepository holidays) throws InvalidClaimException {
374	        LocalDate date = values.date() != null ? values.date() : settings.claimDate(person.sheetId());
375	        int terms = terms(person, date, settings);
376	        LocalDate dueBy = holidays.businessDaysAfter(person.sheetId(), date, terms);
377	        if (periods.closedOn(person.sheetId(), dueBy)) {
378	            throw new InvalidClaimException("The claim's due-by is inside a closed period");
379	        }
380	        if (!person.mayClaimOn(date)) {
381	            throw new InvalidClaimException("The claim's date is after the person's retirement date");
382	        }
383	        checkRef(person.sheetId(), values, null, claims);
384	        return new Checked(date, Corrections.check(person.sheetId(), person.id(), values, claims), dueBy, terms);
385	    }
386	
387	    /** Refuses a reference another claim of the sheet already has, comparing without regard to case; {@code self} is the
388	     *  claim being edited (null for an add), whose own reference does not count. */
389	    public static void checkRef(String sheetId, ClaimValues values, Long self, ClaimRepository claims) throws InvalidClaimException {
390	        if (values.ref() != null && claims.refUsed(sheetId, values.ref(), self)) {
391	            throw new InvalidClaimException("The reference " + values.ref() + " is already used on the sheet");
392	        }
393	    }
394	
395	    /** The due-by a claim of the person dated the date is fixed with as it is added: the terms-th business day after its date (see
396	     *  HolidayRepository.businessDaysAfter), the terms being the person's own, else those of their grade in force on that date (the
397	     *  holidays on the sheet now decide; one added later works it out again, see ClaimRepository#refixDueBys). */
398	    public static LocalDate dueBy(Person person, LocalDate date, SettingRepository settings, HolidayRepository holidays) {
399	        return holidays.businessDaysAfter(person.sheetId(), date, terms(person, date, settings));
400	    }
401	
402	    /** The terms a claim of the person dated the date is fixed with: the person's own, else those of their grade in force on
403	     *  that date. The claim keeps them, so its due-by can be worked out again when a holiday is added (see ClaimRepository#refixDueBys). */
404	    public static int terms(Person person, LocalDate date, SettingRepository settings) {
405	        return settings.terms(person.sheetId(), person.terms(), person.gradeOn(date), date);
406	    }
407	
408	    /** Whether opening the claim would take its person past the cap of the period its due-by falls in: they already have
409	     *  that many OPEN or PENDING claims in it (a period with no cap, or no period: never). */
410	    public static boolean overCap(Claim claim, PeriodRepository periods, ClaimRepository claims) {
411	        Period period = periods.containing(claim.sheetId(), claim.dueBy());
412	        return period != null && period.cap() != null
413	                && claims.heldIn(claim.sheetId(), claim.personId(), period.from(), period.to()) >= period.cap();
414	    }
415	
416	    /** A claim's date, the number it corrects (null when none), its due-by and the terms it was fixed with, once its rules are kept. */
417	    public record Checked(LocalDate date, String corrects, LocalDate dueBy, int terms) {
418	    }
419	}
