430	 * Stores the new status. Opening gives the claim its number (see ClaimNumbering). A change another user made first (the
431	 * stored status is no longer the one this change started from) is refused, and the transaction gives back the number.
432	 * A settle forgets any settle batch the claim had (a bulk settle then marks its own; see SettleClaims). A void given a reason keeps it (see VoidReasonRepository). A stored change adds its line to the claim's status log (see ClaimLog).
433	 */
434	public class SaveClaimStatus {
435	    public void save(@Val Claim claim, @Val ClaimStatusChange change, ClaimRepository claims, PeriodRepository periods,
436	            SettingRepository settings, SheetRepository sheets, ClaimLog log, VoidReasonRepository voidReasons, Out<Claim> saved,
437	            Out<ClaimNumber> number) throws InvalidClaimStatusException {
438	        Claim toSave = claim;
439	        if (change.action() == ClaimAction.OPEN) {
440	            String next = ClaimNumbering.next(claim, claims, periods, settings, sheets);
441	            toSave = new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
442	                    claim.note(), claim.status(), next, claim.due(), claim.openedBy(), claim.stated(), claim.statedDue(), claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(), claim.ref(), claim.tags());
443	            number.set(new ClaimNumber(next));
444	        }
445	        ClaimStatus from = switch (change.action()) {
446	            case OPEN -> ClaimStatus.DRAFT;
447	            case SETTLE -> ClaimStatus.OPEN;
448	            case APPROVE, REJECT -> ClaimStatus.PENDING;
449	            case RESETTLE -> ClaimStatus.SETTLED;
450	            case DELETE -> ClaimStatus.DRAFT;
451	            case RESTORE -> ClaimStatus.DELETED;
452	            case VOID -> null;
453	        };
454	        boolean stored = from != null ? claims.updateStatus(toSave, from)
455	                : claims.updateStatus(toSave, ClaimStatus.DRAFT) || claims.updateStatus(toSave, ClaimStatus.OPEN)
456	                        || claims.updateStatus(toSave, ClaimStatus.PENDING)
457	                        || claims.updateStatus(toSave, ClaimStatus.SETTLED);
458	        if (!stored) {
459	            throw new InvalidClaimStatusException("The claim was changed by someone else");
460	        }
461	        if (change.action() == ClaimAction.VOID && !change.reason().isEmpty()) {
462	            voidReasons.voided(toSave.sheetId(), toSave.id(), change.reason());
463	        }
464	        if (change.action() == ClaimAction.SETTLE) {
465	            claims.unbatch(toSave);
466	        }
467	        log.write(toSave, change.by());
468	        saved.set(toSave);
469	    }
470	}
