package net.officefloor.hq.app.claim;

/** A claim's status. Only OPEN, PENDING and SETTLED claims count toward claimed and the totals. PENDING is a claim a
 *  clerk settled above the clerk limit, waiting for a steward to approve (SETTLED) or reject (back to OPEN) it. DELETED is a
 *  deleted DRAFT: it counts nowhere and takes no action but a restore (DRAFT again) on the sheet-today it was deleted. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.voidreason.VoidReasonRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Moves the claim to its new status: DRAFT to OPEN, OPEN to SETTLED (or PENDING), PENDING to SETTLED (approve) or back
 * to OPEN (reject), DRAFT, OPEN or PENDING to VOID. A voided claim keeps
 * its number (never given again). Settling fixes the claim's due: its amount at its
 * person's grade's rate in force on the claim's date, rounded by its rounding (see Rounding) and at least the sheet's floor (left live when no rate applies),
 * or the figure a statement bound it to, with its late charge as of the sheet's today frozen in (see LateCharge).
 * Opening records who opened the claim; that user cannot settle nor approve it (four eyes), nor can the user who last
 * edited it (see ClaimRepository#editedBy). A claim whose due is
 * above the proof threshold in force on its date (its person's grade's on that date when one is set, else the sheet's; if any) cannot be settled nor approved while its proofs
 * count is 0 (checked before the clerk limit, so it never goes PENDING); a due of n/a is within any threshold. A claim whose due-by falls inside a closed
 * period cannot change status, nor can a deferred claim be settled (see ClaimDue#deferred). A clerk (any user not made a steward) settling a claim whose due is above the sheet's
 * clerk limit, if it has one, makes it PENDING instead (its due left live, not bound by a statement); a due of n/a is
 * within any limit. A steward settles anything. Only a steward approves a PENDING claim (fixing its live figure, late
 * charge included, at that moment) or rejects it (OPEN again, bound again by its statement if one bound it).
 * A claim whose due (as it shows: its live figure at least the floor, or the figure a statement bound it to) is above
 * the sheet's note threshold in force on its date (if it has one) cannot be opened while its note is empty; a due of
 * n/a is within any threshold (see #needsNote). Nor can a claim be opened when its person already has as many OPEN or PENDING
 * claims in the period its due-by falls in as the period's cap (see ClaimRules#overCap).
 * Opening, settling and voiding are each taken only by the roles the sheet's permission allows (see SettingRepository#permits).
 * While the sheet has void reasons, a void needs one of them (see VoidReasonRepository); a reason not on its list is refused.
 * Only a steward voids a SETTLED claim, and only within 7 days of its settlement (the sheet's today on its status log's
 * latest SETTLED line) by the sheet's today; its frozen figure is kept on it but, VOID, it leaves every total.
 * Only a steward re-settles a SETTLED claim (not one whose due-by falls inside a closed period): its due is fixed again at the figure
 * it would have today as an OPEN claim bound by no statement (today's rates, grades, floor and late charge).
 * A DRAFT claim (not one whose due-by falls inside a closed period) is deleted (DELETED: it counts nowhere), and a DELETED
 * one restored (DRAFT again), but only on the sheet's today it was deleted (its status log's latest DELETED line).
 */
public class ApplyClaimStatus {

    /** How many days after its settlement a steward may still void a SETTLED claim. */
    static final int VOID_SETTLED_DAYS = 7;

    public void apply(@Val Claim claim, @Val ClaimStatusChange change, PersonRepository people, RateRepository rates,
            PeriodRepository periods, SettingRepository settings, RoleRepository roles, SheetRepository sheets, ClaimRepository claims, ClaimLog log, VoidReasonRepository voidReasons, Out<Claim> changed, Out<ClaimNumber> number, Out<PreviousDue> previous) throws InvalidClaimStatusException {
        boolean allowed = switch (change.action()) {
            case OPEN -> claim.status() == ClaimStatus.DRAFT;
            case SETTLE -> claim.status() == ClaimStatus.OPEN;
            case APPROVE, REJECT -> claim.status() == ClaimStatus.PENDING;
            case VOID -> claim.status() == ClaimStatus.DRAFT || claim.status() == ClaimStatus.OPEN
                    || claim.status() == ClaimStatus.PENDING || claim.status() == ClaimStatus.SETTLED;
            case RESETTLE -> claim.status() == ClaimStatus.SETTLED;
            case DELETE -> claim.status() == ClaimStatus.DRAFT;
            case RESTORE -> claim.status() == ClaimStatus.DELETED;
        };
        if (!allowed) {
            throw new InvalidClaimStatusException("A " + claim.status() + " claim cannot be made " + change.to());
        }
        if (periods.closedOn(claim.sheetId(), claim.dueBy())) {
            throw new InvalidClaimStatusException("The claim's due-by is inside a closed period");
        }
        if (change.action() == ClaimAction.RESTORE && !sheets.today(claim.sheetId()).equals(log.deletedOn(claim))) {
            throw new InvalidClaimStatusException("A deleted claim can only be restored on the sheet-today it was deleted");
        }
        if (change.action() == ClaimAction.SETTLE && ClaimDue.deferred(claim, sheets.today(claim.sheetId()))) {
            throw new InvalidClaimStatusException("A deferred claim cannot be settled until the date it is deferred until");
        }
        String role = roles.roleOf(claim.sheetId(), change.by());
        boolean steward = RoleRepository.STEWARD.equals(role);
        String permission = switch (change.action()) {
            case OPEN -> "open";
            case SETTLE -> "settle";
            case VOID -> "void";
            default -> null;
        };
        if (permission != null && !settings.permits(claim.sheetId(), permission, role)) {
            throw new InvalidClaimStatusException("A " + role + " may not " + permission + " a claim");
        }
        if (change.action() == ClaimAction.VOID && !change.reason().isEmpty()
                ? !voidReasons.has(claim.sheetId(), change.reason())
                : change.action() == ClaimAction.VOID && voidReasons.any(claim.sheetId())) {
            throw new InvalidClaimStatusException("A void needs a reason from the sheet's list of void reasons");
        }
        if (change.action() == ClaimAction.OPEN && needsNote(claim, people, rates, settings,
                LateCharge.of(claim.sheetId(), sheets, settings, claims))) {
            throw new InvalidClaimStatusException("A claim whose due is above the note threshold needs a note to be opened");
        }
        if (change.action() == ClaimAction.OPEN && ClaimRules.overCap(claim, periods, claims)) {
            throw new InvalidClaimStatusException("The person already has as many open claims in the period as its cap allows");
        }
        if ((change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE)
                && change.by().equals(claim.openedBy())) {
            throw new InvalidClaimStatusException("The user who opened a claim cannot settle nor approve it");
        }
        if ((change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE)
                && change.by().equals(claims.editedBy(claim))) {
            throw new InvalidClaimStatusException("The user who last edited a claim cannot settle nor approve it");
        }
        if ((change.action() == ClaimAction.APPROVE || change.action() == ClaimAction.REJECT) && !steward) {
            throw new InvalidClaimStatusException("Only a steward approves or rejects a pending claim");
        }
        if (change.action() == ClaimAction.VOID && claim.status() == ClaimStatus.SETTLED) {
            if (!steward) {
                throw new InvalidClaimStatusException("Only a steward voids a settled claim");
            }
            LocalDate settledOn = log.settledOn(claim);
            if (settledOn == null || sheets.today(claim.sheetId()).isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
                throw new InvalidClaimStatusException("A settled claim can only be voided within "
                        + VOID_SETTLED_DAYS + " days of its settlement");
            }
        }
        if (change.action() == ClaimAction.RESETTLE && !steward) {
            throw new InvalidClaimStatusException("Only a steward re-settles a claim");
        }
        ClaimStatus to = change.to();
        LateCharge late = LateCharge.of(claim.sheetId(), sheets, settings, claims);
        BigDecimal settledDue;
        if (change.action() == ClaimAction.RESETTLE) {
            Claim asOpen = new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                    claim.note(), ClaimStatus.OPEN, claim.number(), null, claim.openedBy(), false, null,
                    claim.corrects(), claim.dueBy(), null, claim.proofs(), claim.splitFrom(), claim.ref(), claim.tags());
            settledDue = late.add(asOpen, due(asOpen, people, rates, late.rounding()), settings.floor(claim.sheetId(), claim.date()));
        } else {
            settledDue = to == ClaimStatus.SETTLED ? late.add(claim, due(claim, people, rates, late.rounding()), settings.floor(claim.sheetId(), claim.date())) : claim.due();
        }
        if ((change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE) && settledDue != null
                && claim.proofs() == 0) {
            Person person = people.find(claim.sheetId(), claim.personId());
            BigDecimal threshold = settings.proofThreshold(claim.sheetId(),
                    person == null ? null : person.gradeOn(claim.date()), claim.date());
            if (threshold != null && settledDue.compareTo(threshold) > 0) {
                throw new InvalidClaimStatusException("A claim whose due is above the proof threshold needs a proof");
            }
        }
        if (change.action() == ClaimAction.SETTLE && settledDue != null && !steward) {
            BigDecimal limit = settings.clerkLimit(claim.sheetId());
            if (limit != null && settledDue.compareTo(limit) > 0) {
                to = ClaimStatus.PENDING;
                settledDue = null;
            }
        }
        number.set(new ClaimNumber(claim.number()));
        previous.set(new PreviousDue(claim.due(), claim.status()));
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                claim.note(), to, claim.number(), settledDue,
                change.action() == ClaimAction.OPEN ? change.by() : claim.openedBy(), claim.stated(), claim.statedDue(), claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(), claim.ref(), claim.tags()));
    }

    /** Whether the claim cannot be opened for want of a note: its note is empty and its due is above the sheet's note
     *  threshold in force on its date (none: never; a due of n/a: never). */
    static boolean needsNote(Claim claim, PersonRepository people, RateRepository rates, SettingRepository settings,
            LateCharge late) {
        if (claim.note() != null && !claim.note().isBlank()) {
            return false;
        }
        BigDecimal threshold = settings.noteThreshold(claim.sheetId(), claim.date());
        if (threshold == null) {
            return false;
        }
        BigDecimal due = late.add(claim, due(claim, people, rates, late.rounding()),
                settings.floor(claim.sheetId(), claim.date()));
        return due != null && due.compareTo(threshold) > 0;
    }

    private static BigDecimal due(Claim claim, PersonRepository people, RateRepository rates, Rounding rounding) {
        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
            return claim.statedDue();
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        return person == null ? null : ClaimDue.live(claim, person.gradeOn(claim.date()), rates, rounding);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the action is open, settle, approve, reject (which needs a reason), void (with the void reason
 *  chosen, if any), resettle, delete or restore. */
public class ValidateClaimStatus {
    public void validate(@RequestBody ClaimStatusRequest request, Out<ClaimStatusChange> change)
            throws InvalidClaimStatusException {
        String action = request == null || request.action() == null ? "" : request.action().trim();
        ClaimAction taken = switch (action) {
            case "open" -> ClaimAction.OPEN;
            case "settle" -> ClaimAction.SETTLE;
            case "approve" -> ClaimAction.APPROVE;
            case "reject" -> ClaimAction.REJECT;
            case "void" -> ClaimAction.VOID;
            case "resettle" -> ClaimAction.RESETTLE;
            case "delete" -> ClaimAction.DELETE;
            case "restore" -> ClaimAction.RESTORE;
            default -> throw new InvalidClaimStatusException("The action must be open, settle, approve, reject, void, resettle, delete or restore");
        };
        ClaimStatus to = switch (taken) {
            case OPEN, REJECT -> ClaimStatus.OPEN;
            case SETTLE, APPROVE, RESETTLE -> ClaimStatus.SETTLED;
            case VOID -> ClaimStatus.VOID;
            case DELETE -> ClaimStatus.DELETED;
            case RESTORE -> ClaimStatus.DRAFT;
        };
        String reason = request.reason() == null ? "" : request.reason().trim();
        if (taken == ClaimAction.REJECT && reason.isEmpty()) {
            throw new InvalidClaimStatusException("A rejection needs a reason");
        }
        change.set(new ClaimStatusChange(taken, to, request.by() == null ? "" : request.by().trim(),
                taken == ClaimAction.REJECT || taken == ClaimAction.VOID ? reason : ""));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.hq.app.watch.WatchRepository;
import net.officefloor.plugin.variable.Val;

/** Writes CLAIM_OPENED, CLAIM_SETTLED, CLAIM_PENDING, CLAIM_APPROVED, CLAIM_REJECTED, CLAIM_VOIDED, CLAIM_RESETTLED, CLAIM_DELETED or CLAIM_RESTORED to the audit
 * file once the status is stored, ending with number=<number> when the claim has one; CLAIM_SETTLED and CLAIM_APPROVED
 * then end with the due they fixed (due=n/a when its grade had no rate), CLAIM_REJECTED with reason=<reason>, CLAIM_RESETTLED with old=<previous due> new=<new due>, and CLAIM_VOIDED of a SETTLED claim with reversed=<its frozen due>, and a CLAIM_VOIDED given a void reason with reason=<reason> last. Then writes the
 * figures the change moved (see Rollup). A settle, approve or re-settle that leaves the claim SETTLED first writes, after
 * its own line, one NOTIFY user=<watcher> person=<name> number=<number> per user watching the claim's person, in the
 * order they started watching. */
public class RecordClaimStatusChanged {
    public void record(@Val Claim claim, @Val ClaimStatusChange change, @Val ClaimNumber number, @Val PreviousDue previous,
            PersonRepository people, WatchRepository watches, @Val RollupBefore before, Rollup rollup, Audit audit) {
        String event = switch (change.action()) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLE -> claim.status() == ClaimStatus.PENDING ? "CLAIM_PENDING" : "CLAIM_SETTLED";
            case APPROVE -> "CLAIM_APPROVED";
            case REJECT -> "CLAIM_REJECTED";
            case VOID -> "CLAIM_VOIDED";
            case RESETTLE -> "CLAIM_RESETTLED";
            case DELETE -> "CLAIM_DELETED";
            case RESTORE -> "CLAIM_RESTORED";
        };
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record(event + " sheet=" + claim.sheetId() + " by=" + change.by() + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
                + " date=" + claim.date() + (number.value() == null ? "" : " number=" + number.value())
                + (change.action() == ClaimAction.RESETTLE
                        ? " old=" + figure(previous.value()) + " new=" + figure(claim.due())
                        : claim.status() == ClaimStatus.SETTLED
                        ? " due=" + (claim.due() == null ? "n/a" : claim.due().toPlainString()) : "")
                + (change.action() == ClaimAction.REJECT ? " reason=" + change.reason() : "")
                + (change.action() == ClaimAction.VOID && previous.status() == ClaimStatus.SETTLED
                        ? " reversed=" + figure(previous.value()) : "")
                + (change.action() == ClaimAction.VOID && !change.reason().isEmpty() ? " reason=" + change.reason() : ""));
        if (person != null && claim.status() == ClaimStatus.SETTLED && (change.action() == ClaimAction.SETTLE
                || change.action() == ClaimAction.APPROVE || change.action() == ClaimAction.RESETTLE)) {
            for (String watcher : watches.watchers(claim.sheetId(), person.id())) {
                audit.record("NOTIFY sheet=" + claim.sheetId() + " by=" + change.by() + " user=" + watcher + " person="
                        + person.name() + " number=" + number.value());
            }
        }
        rollup.record(claim.sheetId(), change.by(), before);
    }

    private static String figure(BigDecimal due) {
        return due == null ? "n/a" : due.toPlainString();
    }
}
package net.officefloor.hq.app.claim;

import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Opens each selected claim that can be opened, in list order (people in list order, see PersonRepository#list; a person's
 * claims newest first): as the single open does, it must be a DRAFT whose due-by is not inside a closed period, nor one with an empty note whose due is above the note threshold
 * (see ApplyClaimStatus#needsNote), nor one that would take its person past its period's cap (see ClaimRules#overCap; those opened
 * before it in the same press count), takes its
 * number (see ClaimNumbering) and records who opened it, adds its OPEN line to its status log (see ClaimLog), then writes CLAIM_OPENED and the figures it moved (see Rollup).
 * A user whose role the sheet does not permit to open opens none. Each that cannot, or is not on the sheet, is left as it is and counted refused.
 */
public class OpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenRequest request, ClaimRepository claims,
            PersonRepository people, RateRepository rates, PeriodRepository periods, SettingRepository settings, RoleRepository roles, SheetRepository sheets, Rollup rollup, Audit audit, ClaimLog log,
            Out<BulkOpenResult> result) {
        String sheet = sheetId.trim();
        Set<Long> selected = new HashSet<>(request.claimIds());
        List<Person> listed = people.list(sheet);
        Map<Long, Integer> personOrder = new HashMap<>();
        for (int i = 0; i < listed.size(); i++) {
            personOrder.put(listed.get(i).id(), i);
        }
        Map<Long, Person> byId = listed.stream().collect(Collectors.toMap(Person::id, (p) -> p));
        List<Claim> chosen = claims.list(sheet).stream().filter((c) -> selected.contains(c.id()))
                .sorted((a, b) -> Integer.compare(personOrder.getOrDefault(a.personId(), Integer.MAX_VALUE),
                        personOrder.getOrDefault(b.personId(), Integer.MAX_VALUE)))
                .toList();
        LateCharge late = LateCharge.of(sheet, sheets, settings, claims);
        int opened = 0;
        if (!settings.permits(sheet, "open", roles.roleOf(sheet, request.by()))) {
            chosen = List.of();
        }
        for (Claim claim : chosen) {
            if (claim.status() != ClaimStatus.DRAFT || periods.closedOn(sheet, claim.dueBy())
                    || ApplyClaimStatus.needsNote(claim, people, rates, settings, late)
                    || ClaimRules.overCap(claim, periods, claims)) {
                continue;
            }
            RollupBefore before = rollup.take(sheet);
            String number = ClaimNumbering.next(claim, claims, periods, settings, sheets);
            Claim toSave = new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                    claim.note(), ClaimStatus.OPEN, number, claim.due(), request.by(), claim.stated(),
                    claim.statedDue(), claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(), claim.ref(), claim.tags());
            if (!claims.updateStatus(toSave, ClaimStatus.DRAFT)) {
                continue;
            }
            opened++;
            log.write(toSave, request.by());
            Person person = byId.get(claim.personId());
            audit.record("CLAIM_OPENED sheet=" + sheet + " by=" + request.by() + " person="
                    + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
                    + " date=" + claim.date() + " number=" + number);
            rollup.record(sheet, request.by(), before);
        }
        result.set(new BulkOpenResult(opened, selected.size() - opened));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;

/** The rules a claim must keep to be added to a person (see AddClaim), checked without writing anything. */
public final class ClaimRules {

    private ClaimRules() {
    }

    /** The claim's date (the sheet's entry date, else its today, when none was given) and the due-by it would be fixed with (see dueBy);
     *  a due-by inside a closed period or a date after the person's retirement date is refused, as is a negative amount that does not
     *  correct a SETTLED claim (see Corrections), or a reference already used on the sheet (see checkRef). */
    public static Checked check(Person person, ClaimValues values, SettingRepository settings, PeriodRepository periods,
            ClaimRepository claims, HolidayRepository holidays) throws InvalidClaimException {
        LocalDate date = values.date() != null ? values.date() : settings.claimDate(person.sheetId());
        int terms = terms(person, date, settings);
        LocalDate dueBy = holidays.businessDaysAfter(person.sheetId(), date, terms);
        if (periods.closedOn(person.sheetId(), dueBy)) {
            throw new InvalidClaimException("The claim's due-by is inside a closed period");
        }
        if (!person.mayClaimOn(date)) {
            throw new InvalidClaimException("The claim's date is after the person's retirement date");
        }
        checkRef(person.sheetId(), values, null, claims);
        return new Checked(date, Corrections.check(person.sheetId(), person.id(), values, claims), dueBy, terms);
    }

    /** Refuses a reference another claim of the sheet already has, comparing without regard to case; {@code self} is the
     *  claim being edited (null for an add), whose own reference does not count. */
    public static void checkRef(String sheetId, ClaimValues values, Long self, ClaimRepository claims) throws InvalidClaimException {
        if (values.ref() != null && claims.refUsed(sheetId, values.ref(), self)) {
            throw new InvalidClaimException("The reference " + values.ref() + " is already used on the sheet");
        }
    }

    /** The due-by a claim of the person dated the date is fixed with as it is added: the terms-th business day after its date (see
     *  HolidayRepository.businessDaysAfter), the terms being the person's own, else those of their grade in force on that date (the
     *  holidays on the sheet now decide; one added later works it out again, see ClaimRepository#refixDueBys). */
    public static LocalDate dueBy(Person person, LocalDate date, SettingRepository settings, HolidayRepository holidays) {
        return holidays.businessDaysAfter(person.sheetId(), date, terms(person, date, settings));
    }

    /** The terms a claim of the person dated the date is fixed with: the person's own, else those of their grade in force on
     *  that date. The claim keeps them, so its due-by can be worked out again when a holiday is added (see ClaimRepository#refixDueBys). */
    public static int terms(Person person, LocalDate date, SettingRepository settings) {
        return settings.terms(person.sheetId(), person.terms(), person.gradeOn(date), date);
    }

    /** Whether opening the claim would take its person past the cap of the period its due-by falls in: they already have
     *  that many OPEN or PENDING claims in it (a period with no cap, or no period: never). */
    public static boolean overCap(Claim claim, PeriodRepository periods, ClaimRepository claims) {
        Period period = periods.containing(claim.sheetId(), claim.dueBy());
        return period != null && period.cap() != null
                && claims.heldIn(claim.sheetId(), claim.personId(), period.from(), period.to()) >= period.cap();
    }

    /** A claim's date, the number it corrects (null when none), its due-by and the terms it was fixed with, once its rules are kept. */
    public record Checked(LocalDate date, String corrects, LocalDate dueBy, int terms) {
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.voidreason.VoidReasonRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Stores the new status. Opening gives the claim its number (see ClaimNumbering). A change another user made first (the
 * stored status is no longer the one this change started from) is refused, and the transaction gives back the number.
 * A settle forgets any settle batch the claim had (a bulk settle then marks its own; see SettleClaims). A void given a reason keeps it (see VoidReasonRepository). A stored change adds its line to the claim's status log (see ClaimLog).
 */
public class SaveClaimStatus {
    public void save(@Val Claim claim, @Val ClaimStatusChange change, ClaimRepository claims, PeriodRepository periods,
            SettingRepository settings, SheetRepository sheets, ClaimLog log, VoidReasonRepository voidReasons, Out<Claim> saved,
            Out<ClaimNumber> number) throws InvalidClaimStatusException {
        Claim toSave = claim;
        if (change.action() == ClaimAction.OPEN) {
            String next = ClaimNumbering.next(claim, claims, periods, settings, sheets);
            toSave = new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                    claim.note(), claim.status(), next, claim.due(), claim.openedBy(), claim.stated(), claim.statedDue(), claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(), claim.ref(), claim.tags());
            number.set(new ClaimNumber(next));
        }
        ClaimStatus from = switch (change.action()) {
            case OPEN -> ClaimStatus.DRAFT;
            case SETTLE -> ClaimStatus.OPEN;
            case APPROVE, REJECT -> ClaimStatus.PENDING;
            case RESETTLE -> ClaimStatus.SETTLED;
            case DELETE -> ClaimStatus.DRAFT;
            case RESTORE -> ClaimStatus.DELETED;
            case VOID -> null;
        };
        boolean stored = from != null ? claims.updateStatus(toSave, from)
                : claims.updateStatus(toSave, ClaimStatus.DRAFT) || claims.updateStatus(toSave, ClaimStatus.OPEN)
                        || claims.updateStatus(toSave, ClaimStatus.PENDING)
                        || claims.updateStatus(toSave, ClaimStatus.SETTLED);
        if (!stored) {
            throw new InvalidClaimStatusException("The claim was changed by someone else");
        }
        if (change.action() == ClaimAction.VOID && !change.reason().isEmpty()) {
            voidReasons.voided(toSave.sheetId(), toSave.id(), change.reason());
        }
        if (change.action() == ClaimAction.SETTLE) {
            claims.unbatch(toSave);
        }
        log.write(toSave, change.by());
        saved.set(toSave);
    }
}
